sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 */
function handler({api, event, helpers, imports}) {

    if((event.elementId == 'add_button' || event.elementId == 'delete_button') && event.name == 'NOW_BUTTON#CLICKED') {

        api.emit("RECORD#RELATED_LIST_REFRESH_REQUESTED", {
            relatedListName: api.context.props.relatedListName
        });

        // Don't dispatch refresh if extension point is adding risk in project focus mode
        if(api.context.props.extensionPoint != "ADD_RISKS_IN_FOCUS_MODE_TO_PROJECT" && api.context.props.extensionPoint != "ADD_RISKS_FROM_LIBRARY_TO_PROJECT_IN_FOCUS_MODE" && api.context.props.extensionPoint != "REMOVE_RISKS_FROM_ASSESSMENT_PROJECT_IN_FOCUS_MODE") {
            api.emit("REFRESH_LIST",{});
        }

        if(api.context.props.extensionPoint == "REMOVE_RISKS_FROM_ASSESSMENT_PROJECT_IN_FOCUS_MODE") {
            var payload = {
                closeModal: true,
                contentMsg: ""
            };
            api.emit("RISK_ASSESSMENT_PROJECT#REFRESH", payload);
        }

    }

    helpers.modal.close();
}
